//! Runtime settings: provider construction and the three security axes.

use std::path::PathBuf;
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use niucode_agent::ApprovalMode;
use niucode_auth::AuthStore;
use niucode_provider::{OpenAiConfig, OpenAiProvider, Preset, Provider, ThinkingMode};
use niucode_tools::{NetworkMode, SandboxMode, SandboxPolicy};

pub struct ProviderBundle {
    pub provider: Arc<dyn Provider>,
    pub provider_id: String,
    pub model: String,
}

pub fn build_provider(
    preset: &str,
    model: Option<&str>,
    no_thinking: bool,
) -> Result<ProviderBundle> {
    let preset = Preset::parse(preset).with_context(|| format!("unknown provider {preset:?}"))?;
    let auth = AuthStore::new().context("initialize auth store")?;
    let credential = auth.resolve(preset.as_str())?.with_context(|| {
        format!(
            "no credential for {}; run `niucode auth set {}` or set {}",
            preset.as_str(),
            preset.as_str(),
            preset.api_key_env()
        )
    })?;

    let provider_id = preset.as_str().to_string();
    let model = model
        .map(str::to_string)
        .unwrap_or_else(|| default_model(&preset));

    let mut config = OpenAiConfig::preset_config(preset)?;
    config.api_key = credential.key.expose().to_string();
    config.model = model.clone();
    if no_thinking && preset == Preset::DeepSeek {
        config.thinking = Some(ThinkingMode::Disabled);
    }
    let provider: Arc<dyn Provider> = Arc::new(OpenAiProvider::for_preset(preset, config)?);
    Ok(ProviderBundle {
        provider,
        provider_id,
        model,
    })
}

fn default_model(preset: &Preset) -> String {
    niucode_provider::find_provider(preset.as_str())
        .map(|descriptor| descriptor.default_model.to_string())
        .unwrap_or_else(|| preset.default_model().to_string())
}

pub fn parse_sandbox(value: &str) -> Result<SandboxMode> {
    match value {
        "read-only" => Ok(SandboxMode::ReadOnly),
        "workspace-write" => Ok(SandboxMode::WorkspaceWrite),
        "full-access" => Ok(SandboxMode::FullAccess),
        other => bail!("unknown sandbox {other:?}; use read-only, workspace-write, or full-access"),
    }
}

pub fn parse_network(value: &str) -> Result<NetworkMode> {
    match value {
        "on" => Ok(NetworkMode::On),
        "off" => Ok(NetworkMode::Off),
        other => bail!("unknown network {other:?}; use on or off"),
    }
}

pub fn parse_approval(value: &str) -> Result<ApprovalMode> {
    match value {
        "ask" => Ok(ApprovalMode::Ask),
        "on-failure" => Ok(ApprovalMode::OnFailure),
        "never" => Ok(ApprovalMode::Never),
        other => bail!("unknown approval {other:?}; use ask, on-failure, or never"),
    }
}

/// Mirror niucode's fallback: without bwrap, `never` is refused and the other
/// modes degrade to explicit per-action approval.
pub fn resolve_policy(
    sandbox: &str,
    approval: &str,
    network: &str,
) -> Result<(SandboxPolicy, ApprovalMode, bool)> {
    let mut approval = parse_approval(approval)?;
    let policy = SandboxPolicy::new(parse_sandbox(sandbox)?, parse_network(network)?);
    let mut allow_unsandboxed = false;

    if policy.backend() == "unavailable" {
        match approval {
            ApprovalMode::Never => bail!(
                "sandbox backend bwrap is unavailable; install bubblewrap or use --approval ask"
            ),
            ApprovalMode::OnFailure => {
                eprintln!(
                    "warning: sandbox backend unavailable; falling back to per-action approval"
                );
                approval = ApprovalMode::Ask;
                allow_unsandboxed = true;
            }
            ApprovalMode::Ask => {
                eprintln!("warning: sandbox backend unavailable; using per-action approval");
                allow_unsandboxed = true;
            }
        }
    }

    Ok((policy, approval, allow_unsandboxed))
}

/// `--thread` is a path argument: resolve relative paths against the process
/// cwd, and fall back to the store's active session when absent.
pub fn resolve_thread(path: Option<PathBuf>, store: &niuse_core::Store) -> Result<PathBuf> {
    match path {
        Some(path) if path.is_absolute() => Ok(path),
        Some(path) => Ok(std::env::current_dir()
            .context("resolve current directory")?
            .join(path)),
        None => Ok(store.session_path()),
    }
}

pub fn resolve_cwd(cwd: Option<PathBuf>) -> Result<PathBuf> {
    let cwd = match cwd {
        Some(path) => path,
        None => std::env::current_dir().context("resolve current directory")?,
    };
    let cwd = cwd
        .canonicalize()
        .with_context(|| format!("resolve working directory {}", cwd.display()))?;
    if !cwd.is_dir() {
        bail!("working directory {} is not a directory", cwd.display());
    }
    Ok(cwd)
}

//! Open-loop commands: list, add, and close promises.

use anyhow::{bail, Context, Result};
use niuse_core::model::one_line;
use niuse_core::policy::secret_reason;
use niuse_core::{Date, LoopItem, Store};
use serde::Serialize;

use super::normalize_id;

#[derive(Debug, Serialize)]
struct LoopJson {
    id: String,
    text: String,
    due: Option<String>,
    done: bool,
    overdue: bool,
}

pub fn loops_list(store: &Store, all: bool, json: bool, overdue_only: bool) -> Result<()> {
    let today = Date::today();
    let loops = store.loops()?;
    if json {
        let items: Vec<LoopJson> = loops
            .iter()
            .filter(|item| all || !item.done)
            .filter(|item| !overdue_only || item.is_overdue(today))
            .map(|item| LoopJson {
                id: format!("l-{}", item.id),
                text: item.text.clone(),
                due: item.due.map(|due| due.to_string()),
                done: item.done,
                overdue: item.is_overdue(today),
            })
            .collect();
        println!("{}", serde_json::to_string_pretty(&items)?);
        return Ok(());
    }
    let open = loops.iter().filter(|item| !item.done).count();
    if overdue_only {
        let overdue = loops.iter().filter(|item| item.is_overdue(today)).count();
        println!("{overdue} 条逾期");
    } else {
        println!("{} 条承诺 · {} 条未完成", loops.len(), open);
    }
    for item in &loops {
        if item.done && !all {
            continue;
        }
        if overdue_only && !item.is_overdue(today) {
            continue;
        }
        let mark = if item.done { "x" } else { " " };
        let due = match item.due {
            Some(due) if item.is_overdue(today) => format!("（截止 {due}，已逾期）"),
            Some(due) => format!("（截止 {due}）"),
            None => String::new(),
        };
        println!("[{mark}] l-{} {}{due}", item.id, item.text);
    }
    Ok(())
}

pub fn loops_add(store: &Store, text: &str, due: Option<&str>) -> Result<()> {
    let text = one_line(text.trim().to_string());
    if text.is_empty() {
        bail!("loop text is empty");
    }
    if let Some(reason) = secret_reason(&text) {
        bail!("refusing to store: looks like a {reason}");
    }
    let due = match due {
        Some(value) => {
            Some(Date::parse(value).with_context(|| format!("invalid due date {value:?}"))?)
        }
        None => None,
    };
    let item = store.add_loop(LoopItem::new(text, due))?;
    if let Err(error) = store.append_metric("loop", &item.id) {
        eprintln!("warning: cannot record metric: {error:#}");
    }
    match item.due {
        Some(due) => println!("l-{} {} (due {due})", item.id, item.text),
        None => println!("l-{} {}", item.id, item.text),
    }
    Ok(())
}

pub fn loops_done(store: &Store, id: &str) -> Result<()> {
    let id = normalize_id(id);
    if store.close_loop(&id)? {
        println!("closed l-{id}");
    } else {
        bail!("no loop l-{id}");
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn manual_loop_persists_with_due_date() {
        let directory = tempfile::tempdir().unwrap();
        let store = Store::at(directory.path().join(".niuse"));
        store.init().unwrap();
        loops_add(&store, "check the pin", Some("2026-10-30")).unwrap();
        let loops = store.loops().unwrap();
        assert_eq!(loops.len(), 1);
        assert_eq!(loops[0].text, "check the pin");
        assert_eq!(loops[0].due, Date::parse("2026-10-30"));
    }

    #[test]
    fn manual_loop_rejects_a_bad_due_date() {
        let directory = tempfile::tempdir().unwrap();
        let store = Store::at(directory.path().join(".niuse"));
        store.init().unwrap();
        assert!(loops_add(&store, "check", Some("2026-13-01")).is_err());
        assert!(store.loops().unwrap().is_empty());
    }
}

//! Session-facing commands: list threads and export a log as Markdown.

use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{bail, Context, Result};
use niucode_core::Event;
use niuse_core::Store;

#[derive(Debug)]
struct ThreadInfo {
    path: PathBuf,
    active: bool,
    events: usize,
    bytes: u64,
    age_secs: u64,
    modified: SystemTime,
    title: Option<String>,
}

pub fn sessions(store: &Store, json: bool) -> Result<()> {
    let entries = collect_sessions(store)?;
    if json {
        let items: Vec<ThreadJson> = entries
            .iter()
            .map(|info| thread_json(store, info))
            .collect();
        println!("{}", serde_json::to_string_pretty(&items)?);
        return Ok(());
    }
    if entries.is_empty() {
        println!("还没有一次性 session。`niuse exec` 会在这里留下日志。");
        return Ok(());
    }
    println!("{} 个一次性 session", entries.len());
    for info in entries {
        let relative = info.path.strip_prefix(store.root()).unwrap_or(&info.path);
        println!(
            "  {:<8} {:>4} events  {:>8}  {}",
            human_age(info.age_secs),
            info.events,
            human_bytes(info.bytes),
            relative.display()
        );
        if let Some(title) = &info.title {
            println!("      {title}");
        }
    }
    Ok(())
}

pub fn threads(store: &Store, active: &Path, json: bool) -> Result<()> {
    let entries = collect_threads(store, active)?;
    if json {
        let items: Vec<ThreadJson> = entries
            .iter()
            .map(|info| thread_json(store, info))
            .collect();
        println!("{}", serde_json::to_string_pretty(&items)?);
        return Ok(());
    }
    if entries.is_empty() {
        println!("还没有主线。第一次对话会自动创建。");
        return Ok(());
    }
    for (index, info) in entries.into_iter().enumerate() {
        let marker = if info.active { "*" } else { " " };
        let relative = info.path.strip_prefix(store.root()).unwrap_or(&info.path);
        println!(
            "{marker} [{}] {:<8} {:>4} events  {:>8}  {}",
            index + 1,
            human_age(info.age_secs),
            info.events,
            human_bytes(info.bytes),
            relative.display()
        );
        if let Some(title) = &info.title {
            println!("    {title}");
        }
    }
    Ok(())
}

#[derive(Debug, serde::Serialize)]
struct ThreadJson {
    path: String,
    active: bool,
    events: usize,
    bytes: u64,
    age_seconds: u64,
    title: Option<String>,
}

fn thread_json(store: &Store, info: &ThreadInfo) -> ThreadJson {
    ThreadJson {
        path: info
            .path
            .strip_prefix(store.root())
            .unwrap_or(&info.path)
            .to_string_lossy()
            .to_string(),
        active: info.active,
        events: info.events,
        bytes: info.bytes,
        age_seconds: info.age_secs,
        title: info.title.clone(),
    }
}

fn jsonl_files(directory: &Path) -> Result<Vec<PathBuf>> {
    if !directory.is_dir() {
        return Ok(Vec::new());
    }
    let mut paths = Vec::new();
    for entry in fs::read_dir(directory).with_context(|| format!("read {}", directory.display()))? {
        let path = entry?.path();
        if path.extension().and_then(|extension| extension.to_str()) == Some("jsonl") {
            paths.push(path);
        }
    }
    Ok(paths)
}

/// One-based index into the same ordering `threads` prints.
pub fn thread_at(store: &Store, active: &Path, index: usize) -> Result<Option<PathBuf>> {
    if index == 0 {
        return Ok(None);
    }
    Ok(collect_threads(store, active)?
        .get(index - 1)
        .map(|info| info.path.clone()))
}

fn collect_threads(store: &Store, active: &Path) -> Result<Vec<ThreadInfo>> {
    let mut entries = Vec::new();
    push_thread(&mut entries, &store.session_path(), Some(active))?;
    for path in jsonl_files(&store.threads_dir())? {
        push_thread(&mut entries, &path, Some(active))?;
    }
    entries.sort_by_key(|entry| std::cmp::Reverse(entry.modified));
    Ok(entries)
}

fn collect_sessions(store: &Store) -> Result<Vec<ThreadInfo>> {
    let mut entries = Vec::new();
    for path in jsonl_files(&store.root().join("sessions"))? {
        push_thread(&mut entries, &path, None)?;
    }
    entries.sort_by_key(|entry| std::cmp::Reverse(entry.modified));
    Ok(entries)
}

fn push_thread(entries: &mut Vec<ThreadInfo>, path: &Path, active: Option<&Path>) -> Result<()> {
    if !path.exists() {
        return Ok(());
    }
    let metadata = fs::metadata(path).with_context(|| format!("stat {}", path.display()))?;
    let modified = metadata.modified().unwrap_or(UNIX_EPOCH);
    let age_secs = SystemTime::now()
        .duration_since(modified)
        .map(|elapsed| elapsed.as_secs())
        .unwrap_or(0);
    let loaded = niucode_core::load(path);
    let events = loaded
        .as_ref()
        .map(|loaded| loaded.events.len())
        .unwrap_or(0);
    let title = loaded
        .as_ref()
        .ok()
        .and_then(|loaded| thread_title(&loaded.events));
    entries.push(ThreadInfo {
        path: path.to_path_buf(),
        active: active.is_some_and(|active| path == active),
        events,
        bytes: metadata.len(),
        age_secs,
        modified,
        title,
    });
    Ok(())
}

fn thread_title(events: &[Event]) -> Option<String> {
    for event in events {
        if let Event::UserMessage { text, .. } = event {
            let line = text.lines().next().unwrap_or(text).trim();
            if line.is_empty() {
                continue;
            }
            let title: String = line.chars().take(60).collect();
            return Some(if line.chars().count() > 60 {
                format!("{title}…")
            } else {
                title
            });
        }
    }

//! Journal commands: list days, search bullets, and add a manual entry.

use anyhow::{bail, Result};
use niuse_core::model::one_line;
use niuse_core::policy::{search_score, secret_reason};
use niuse_core::{Date, JournalDay, Store};

#[derive(Debug, serde::Serialize)]
struct JournalDayJson {
    date: String,
    bullets: Vec<String>,
}

#[derive(Debug, serde::Serialize)]
struct JournalHitJson {
    date: String,
    text: String,
}

fn window(days: usize) -> usize {
    if days == 0 {
        usize::MAX
    } else {
        days
    }
}

pub fn journal_show(store: &Store, days: usize, json: bool) -> Result<()> {
    let days = store.recent_journal(window(days))?;
    if json {
        let items: Vec<JournalDayJson> = days
            .iter()
            .map(|day| JournalDayJson {
                date: day.date.to_string(),
                bullets: day.bullets.clone(),
            })
            .collect();
        println!("{}", serde_json::to_string_pretty(&items)?);
        return Ok(());
    }
    if days.is_empty() {
        println!("（还没有 journal。）");
        return Ok(());
    }
    for day in days {
        println!("## {}", day.date);
        for bullet in &day.bullets {
            println!("- {bullet}");
        }
        println!();
    }
    Ok(())
}

pub fn journal_add(store: &Store, text: &str) -> Result<()> {
    let text = one_line(text.trim().to_string());
    if text.is_empty() {
        bail!("journal text is empty");
    }
    if let Some(reason) = secret_reason(&text) {
        bail!("refusing to store: looks like a {reason}");
    }
    if store.append_journal(Date::today(), std::slice::from_ref(&text))? {
        if let Err(error) = store.append_metric("journal", "1") {
            eprintln!("warning: cannot record metric: {error:#}");
        }
        println!("journal +1");
    }
    Ok(())
}

pub fn journal_search(store: &Store, query: &str, json: bool) -> Result<()> {
    let query = query.trim();
    if query.is_empty() {
        bail!("usage: niuse journal --search <query>");
    }
    let days = store.recent_journal(usize::MAX)?;
    let hits = rank_journal(query, &days);
    if json {
        let items: Vec<JournalHitJson> = hits
            .iter()
            .map(|(_, day, text)| JournalHitJson {
                date: day.date.to_string(),
                text: (*text).to_string(),
            })
            .collect();
        println!("{}", serde_json::to_string_pretty(&items)?);
        return Ok(());
    }
    if hits.is_empty() {
        println!("没有匹配「{query}」的日记。");
        return Ok(());
    }
    println!("{} 条匹配「{query}」", hits.len());
    for (_, day, bullet) in hits.iter().take(10) {
        println!("{}  {bullet}", day.date);
    }
    Ok(())
}

fn rank_journal<'a>(query: &str, days: &'a [JournalDay]) -> Vec<(f64, &'a JournalDay, &'a str)> {
    let mut hits = Vec::new();
    for day in days {
        for bullet in &day.bullets {
            let score = search_score(query, bullet, &[]);
            if score >= 0.2 {
                hits.push((score, day, bullet.as_str()));
            }
        }
    }
    hits.sort_by(|left, right| {
        right
            .0
            .partial_cmp(&left.0)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    hits
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn manual_journal_entry_persists() {
        let directory = tempfile::tempdir().unwrap();
        let store = Store::at(directory.path().join(".niuse"));
        store.init().unwrap();
        journal_add(&store, "decided to ship the config file").unwrap();
        let days = store.recent_journal(1).unwrap();
        assert_eq!(days.len(), 1);
        assert!(days[0]
            .bullets
            .iter()
            .any(|bullet| bullet.contains("config file")));
    }

    #[test]
    fn zero_days_means_the_whole_journal() {
        assert_eq!(window(0), usize::MAX);
        assert_eq!(window(7), 7);
    }

    #[test]
    fn journal_search_ranks_substring_hits() {
        let day = JournalDay {
            date: Date::parse("2026-10-21").unwrap(),
            bullets: vec![
                "decided to use cargo nextest".into(),
                "unrelated thought about lunch".into(),
            ],
        };
        let days = vec![day];
        let hits = rank_journal("nextest", &days);
        assert_eq!(hits.len(), 1);
        assert_eq!(hits[0].2, "decided to use cargo nextest");
    }

    #[test]
    fn journal_search_returns_nothing_for_unrelated_queries() {
        let day = JournalDay {
            date: Date::parse("2026-10-21").unwrap(),
            bullets: vec!["decided to use cargo nextest".into()],
        };
        assert!(rank_journal("kubernetes", &[day]).is_empty());
    }
}

//! Identity and user-profile commands.

use std::io::{self, Write};

use anyhow::{bail, Result};
use niuse_core::policy::secret_reason;
use niuse_core::Store;

use super::edit_markdown;

pub fn user_show(store: &Store, json: bool) -> Result<()> {
    let text = store.user()?;
    if json {
        let payload = serde_json::json!({
            "path": store.user_path().display().to_string(),
            "text": text,
        });
        println!("{}", serde_json::to_string_pretty(&payload)?);
        return Ok(());
    }
    println!("{}", store.user_path().display());
    match text {
        Some(text) => print!("{text}"),
        None => println!("(missing; run `niuse bootstrap --profile` or `niuse user edit`)"),
    }
    Ok(())
}

pub fn user_edit(store: &Store) -> Result<()> {
    let current = store.user()?.unwrap_or_else(|| {
        "# 关于我\n\n- 我在做什么：\n- 我的工作方式：\n- 我的雷区：\n".to_string()
    });
    let Some(updated) = edit_markdown(&current) else {
        println!("no change");
        return Ok(());
    };
    if let Some(reason) = secret_reason(&updated) {
        bail!("refusing to save user.md: looks like a {reason}");
    }
    store.write_user(&updated)?;
    if let Err(error) = store.append_metric("user_edit", "") {
        eprintln!("warning: cannot record metric: {error:#}");
    }
    println!("updated {}", store.user_path().display());
    Ok(())
}

pub fn identity_edit(store: &Store) -> Result<()> {
    let current = store
        .identity()?
        .unwrap_or_else(|| "# 你是 niuse\n\n描述它是谁、它的边界和说话方式。\n".to_string());
    let Some(updated) = edit_markdown(&current) else {
        println!("no change");
        return Ok(());
    };
    if let Some(reason) = secret_reason(&updated) {
        bail!("refusing to save identity.md: looks like a {reason}");
    }
    store.write_identity(&updated)?;
    if let Err(error) = store.append_metric("identity_edit", "") {
        eprintln!("warning: cannot record metric: {error:#}");
    }
    println!("updated {}", store.identity_path().display());
    Ok(())
}

pub fn identity_show(store: &Store, json: bool) -> Result<()> {
    let text = store.identity()?;
    if json {
        let payload = serde_json::json!({
            "path": store.identity_path().display().to_string(),
            "text": text,
        });
        println!("{}", serde_json::to_string_pretty(&payload)?);
        return Ok(());
    }
    match text {
        Some(text) => {
            println!("{}", store.identity_path().display());
            println!();
            print!("{text}");
        }
        None => println!(
            "还没有 identity.md。运行 `niuse identity init` 创建：{}",
            store.identity_path().display()
        ),
    }
    Ok(())
}

pub fn identity_init(store: &Store, force: bool) -> Result<()> {
    let path = store.identity_path();
    if path.exists() && !force {
        bail!(
            "{} already exists; pass --force to overwrite",
            path.display()
        );
    }

    let answers = [
        ask("你叫它什么名字", "niuse")?,
        ask("它是你的什么（搭档 / 同事 / 朋友）", "工程搭档")?,
        ask("用三个词描述它的性格", "直接、克制、有判断")?,
        ask("它应该坚持的一条原则", "不知道就说不知道")?,
        ask("它绝对不能做的一件事", "奉承我、替我做决定")?,
        ask("它说话的方式", "先给结论，再给理由；不说客套话")?,
        ask("它应该主动提醒你什么", "未完成的承诺和明显的风险")?,
        ask("它怎么称呼你", "你")?,
    ];

    let name = &answers[0];
    let relationship = &answers[1];
    let style = &answers[5];
    let text = format!(
        "# 你是 {name}\n\n\
         你是一个{relationship}，不是一个通用助手。你称呼对方为「{user}」。\n\n\
         ## 性格\n{persona}\n\n\
         ## 坚持\n- {principle}\n\n\
         ## 边界\n- {boundary}\n\n\
         ## 说话方式\n{style}\n\n\
         ## 主动提醒\n{reminder}\n",
        user = answers[7],
        persona = answers[2],
        principle = answers[3],
        boundary = answers[4],
        style = style,
        reminder = answers[6],
    );
    if let Some(reason) = secret_reason(&text) {
        bail!("refusing to save identity.md: looks like a {reason}");
    }
    store.write_identity(&text)?;
    println!("wrote {}", path.display());
    Ok(())
}

fn ask(prompt: &str, default: &str) -> Result<String> {
    print!("{prompt} [{default}]: ");
    let _ = io::stdout().flush();
    let mut line = String::new();
    if io::stdin().read_line(&mut line)? == 0 {
        return Ok(default.to_string());
    }
    let answer = line.trim();
    Ok(if answer.is_empty() {
        default.to_string()
    } else {
        answer.to_string()
    })
}

