//! Minimal terminal rendering for `niuse`. The niucode TUI lives behind a
//! binary-only crate, so niuse owns this small renderer and keeps the turn loop
//! as the single source of events.

use std::env;
use std::io::{self, IsTerminal, Write};

use niucode_agent::{AgentEvent, ApprovalRequest};
use niucode_tools::{ChangePreview, LineKind, PreviewBody};
use niuse_core::{parse, Parsed, StreamFilter};

/// Dim, yellow, or red only on a real terminal that has not opted out.
fn styled(code: &str, text: &str) -> String {
    if io::stdout().is_terminal() && env::var_os("NO_COLOR").is_none() {
        format!("\x1b[{code}m{text}\x1b[0m")
    } else {
        text.to_string()
    }
}

/// Color code for one diff line: headers bold, additions green, removals
/// red, hunk headers cyan. Context lines are left alone.
fn diff_style(line: &str) -> Option<&'static str> {
    if line.starts_with("+++") || line.starts_with("---") {
        Some("1")
    } else if line.starts_with('+') {
        Some("32")
    } else if line.starts_with('-') {
        Some("31")
    } else if line.starts_with("@@") {
        Some("36")
    } else {
        None
    }
}

fn paint_diff(line: &str) -> String {
    match diff_style(line) {
        Some(code) => styled(code, line),
        None => line.to_string(),
    }
}

/// Short token counts: `999`, `1.5k`, `12k`.
pub(crate) fn compact_tokens(tokens: u64) -> String {
    if tokens < 1_000 {
        return tokens.to_string();
    }
    let value = tokens as f64 / 1_000.0;
    if value >= 10.0 {
        format!("{value:.0}k")
    } else {
        format!("{value:.1}k").replace(".0k", "k")
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct UsageTotals {
    pub input: u64,
    pub output: u64,
    pub cached: u64,
}

pub struct Renderer {
    filter: StreamFilter,
    at_line_start: bool,
    steps: u64,
    usage_input: u64,
    usage_output: u64,
    usage_cached: u64,
}

impl Renderer {
    pub fn new() -> Self {
        Self {
            filter: StreamFilter::new(),
            at_line_start: true,
            steps: 0,
            usage_input: 0,
            usage_output: 0,
            usage_cached: 0,
        }
    }

    pub fn event(&mut self, event: AgentEvent) {
        match event {
            AgentEvent::TextDelta(delta) => {
                let visible = self.filter.push(&delta);
                if !visible.is_empty() {
                    print!("{visible}");
                    let _ = io::stdout().flush();
                    self.at_line_start = visible.ends_with('\n');
                }
            }
            AgentEvent::ReasoningDelta(_) => {}
            AgentEvent::ToolCall { name, input } => {
                self.newline();
                let line = format!("→ {} {}", name, truncate(&input.to_string(), 180));
                println!("{}", styled("2", &line));
                self.at_line_start = true;
            }
            AgentEvent::ToolResult {
                name, ok, summary, ..
            } => {
                self.newline();
                let mark = if ok { "✓" } else { "✗" };
                let line = format!("{mark} {name}: {}", truncate(&summary, 240));
                let line = if ok {
                    styled("2", &line)
                } else {
                    styled("31", &line)
                };
                println!("{line}");
                self.at_line_start = true;
            }
            AgentEvent::Warning(warning) => {
                self.newline();
                println!("{}", styled("33", &format!("! {warning}")));
                self.at_line_start = true;
            }
            AgentEvent::Compaction {
                before_tokens,
                after_tokens,
                ..
            } => {
                self.newline();
                println!("[compacted {before_tokens} → {after_tokens} tokens]");
                self.at_line_start = true;
            }
            AgentEvent::TurnEnd { usage } => {
                self.steps += 1;
                self.usage_input += usage.input_tokens;
                self.usage_output += usage.output_tokens;
                self.usage_cached += usage.cached_tokens;
            }
            AgentEvent::Phase(_) => {}
        }
    }

    pub fn usage(&self) -> UsageTotals {
        UsageTotals {
            input: self.usage_input,
            output: self.usage_output,
            cached: self.usage_cached,
        }
    }

    /// Flush held text, print a final newline, and return the parsed answer.
    pub fn finish(&mut self) -> Parsed {
        let (tail, raw) = self.filter.finish();
        if !tail.is_empty() {
            print!("{tail}");
            let _ = io::stdout().flush();
            self.at_line_start = tail.ends_with('\n');
        }
        self.newline();
        if self.steps > 0 {
            let mut line = format!(
                "  {} step{} · {} in · {} out",
                self.steps,
                if self.steps == 1 { "" } else { "s" },
                compact_tokens(self.usage_input),
                compact_tokens(self.usage_output)
            );
            if self.usage_cached > 0 {
                line.push_str(&format!(" · {} cached", compact_tokens(self.usage_cached)));
            }
            println!("{}", styled("2", &line));
        }
        parse(&raw)
    }

    fn newline(&mut self) {
        if !self.at_line_start {
            println!();
            let _ = io::stdout().flush();
            self.at_line_start = true;
        }
    }
}

impl Default for Renderer {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ApprovalDecision {
    Allow,
    Deny,
    ShowFull,
}

fn parse_approval(input: &str, has_full: bool) -> ApprovalDecision {
    match input.trim().to_lowercase().as_str() {
        "y" | "yes" => ApprovalDecision::Allow,
        "d" | "diff" if has_full => ApprovalDecision::ShowFull,
        _ => ApprovalDecision::Deny,
    }

//! System-prompt assembly.
//!
//! Stable sections come first (persona, identity, user, memory, protocol) so the
//! provider can reuse its prompt cache; volatile sections (today, loops,
//! journal) come last. The whole prompt is built once per session.

use crate::date::Date;
use crate::model::{Goal, JournalDay, LoopItem, MemoryEntry, PlanStep};

pub const IDENTITY_BUDGET: usize = 600;
pub const USER_BUDGET: usize = 600;
pub const GOAL_BUDGET: usize = 300;
pub const PLAN_BUDGET: usize = 300;
pub const MEMORY_BUDGET: usize = 2_000;
pub const LOOP_BUDGET: usize = 300;
pub const JOURNAL_BUDGET: usize = 600;

pub const BASE: &str = "你是一个长期陪伴这位用户的工程伙伴。\n\
你的名字、语气与边界由后面的「你是谁」一节定义；本段只描述工作方式，产品名不是你的名字。\n\
你不是通用助手。你的价值不在「什么都能答」，而在三件事：记得他做过的判断、追踪你自己许下的承诺、在他判断错的时候开口。\n\
工作方式：\n\
- 具体优于笼统。引用过去的决定时说清楚是哪一次、为什么，不要泛泛地说「你喜欢简洁」。\n\
- 不表演情绪，不用昵称轰炸，不主动抒情。\n\
- 不同意就直说，给出理由，对事不对人。\n\
- 不确定就去查；查不到就说不知道，不要补全。\n\
- 记忆是偏好，不是法律。与当前证据冲突时以证据为准，并指出你不同意哪一条。";

pub const PROTOCOL: &str = "你可以在回答的最后输出以下块。运行时会解析它们，并从用户看到的文本里剥离；不要在正文里提到这些块。\n\n\
<<niuse:memory kind=preference tags=rust,testing>>\n\
一句能独立看懂、跨项目仍然成立的结论\n\
<</niuse:memory>>\n\n\
<<niuse:loop due=2026-10-22>>\n\
你答应过、或用户交代你下次要做的事\n\
<</niuse:loop>>\n\n\
<<niuse:journal>>\n\
- 今天发生的决定、转折、未解问题或情绪变化（最多 3 条）\n\
<</niuse:journal>>\n\n\
规则：\n\
- 每轮最多一个 memory 块；没有值得记的就不要输出，连续多轮没有候选是正常的。\n\
- 只记「跨会话仍然有用、在仓库里 grep 不出来、一句话说得清」的内容。\n\
- memory 写偏好、决策、踩坑；不要写代码事实、环境配置、别人的信息。\n\
- 如果怀疑有一条旧记忆没有注入，向用户请求 `/recall <关键词>`；不要凭印象补全。\n\
- 绝不把密钥、token、密码、客户名写进任何块。\n\
- journal 只写与上次不同的东西；「今天修了个 bug」这种流水账不要写。";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Composition {
    pub system: String,
    pub memory_injected: usize,
    pub memory_dropped: usize,
    pub tokens: usize,
}

/// Conservative token estimate: ASCII averages four characters per token,
/// every non-ASCII character counts as one. Matches niucode's estimator.
pub fn estimate_text_tokens(text: &str) -> usize {
    let mut ascii = 0usize;
    let mut other = 0usize;
    for character in text.chars() {
        if character.is_ascii() {
            ascii += 1;
        } else {
            other += 1;
        }
    }
    ascii.div_ceil(4) + other
}

pub fn compose(
    identity: Option<&str>,
    user: Option<&str>,
    memories: &[MemoryEntry],
    loops: &[LoopItem],
    journal: &[JournalDay],
    today: Date,
) -> Composition {
    compose_with_plan(identity, user, &[], &[], memories, loops, journal, today)
}

pub fn compose_with_goals(
    identity: Option<&str>,
    user: Option<&str>,
    goals: &[Goal],
    memories: &[MemoryEntry],
    loops: &[LoopItem],
    journal: &[JournalDay],
    today: Date,
) -> Composition {
    compose_with_plan(identity, user, goals, &[], memories, loops, journal, today)
}

#[allow(clippy::too_many_arguments)]
pub fn compose_with_plan(
    identity: Option<&str>,
    user: Option<&str>,
    goals: &[Goal],
    plan: &[PlanStep],
    memories: &[MemoryEntry],
    loops: &[LoopItem],
    journal: &[JournalDay],
    today: Date,
) -> Composition {
    let mut sections: Vec<(&str, String)> = Vec::new();

    match identity.map(str::trim).filter(|text| !text.is_empty()) {
        Some(identity) => sections.push((
            "你是谁",
            format!(
                "以下是你名字、语气与边界的唯一真源；如果本 prompt 的其他段落（包括产品名）与本段冲突，以本段为准。\n\n{}",
                truncate_to_tokens(identity, IDENTITY_BUDGET)
            ),
        )),
        None => sections.push((
            "你是谁",
            "当前还没有 identity.md。\n\n如果用户问「你是谁」「你叫什么」「介绍一下你自己」：只用一句话回答「我还没有名字。运行 `niuse identity init` 给我一个。」\n不要调用任何工具，不要用产品名充数，不要展开工作方式。\n\n其他情况下，你仍然是一个没有名字的工程伙伴。".into(),
        )),
    }
    if let Some(user) = user.map(str::trim).filter(|text| !text.is_empty()) {
        sections.push(("你在和谁一起工作", truncate_to_tokens(user, USER_BUDGET)));
    }

    let goal_text = goal_section(goals);
    if !goal_text.is_empty() {
        sections.push(("当前目标", goal_text));
    }

    let plan_text = plan_section(plan);
    if !plan_text.is_empty() {
        sections.push(("当前计划", plan_text));
    }

    let (memory_text, memory_injected, memory_dropped) = memory_section(memories, today);
    if !memory_text.is_empty() {
        sections.push((
            "长期记忆",
            format!(
                "以下是你和用户长期积累的判断。它们是偏好，不是法律；与当前证据冲突时以证据为准，并指出你不同意哪一条。\n\n{memory_text}"
            ),
        ));
    }

    // Constant: keeping it before the volatile sections lengthens the stable
    // cache prefix.
    sections.push(("记忆协议", PROTOCOL.to_string()));
    sections.push(("今天", today.format()));

    let loop_text = loop_section(loops, today);
    if !loop_text.is_empty() {
        sections.push(("未完成的承诺", loop_text));
    }

    let journal_text = journal_section(journal);
    if !journal_text.is_empty() {
        sections.push(("最近几天", journal_text));
    }

    let mut system = String::from(BASE);
    for (title, body) in &sections {
        system.push_str("\n\n## ");
        system.push_str(title);
        system.push('\n');
        system.push_str(body);
    }

    Composition {
        tokens: estimate_text_tokens(&system),
        system,
        memory_injected,
        memory_dropped,
    }
}

fn plan_section(steps: &[PlanStep]) -> String {
    let open: Vec<&PlanStep> = steps.iter().filter(|step| !step.done).take(6).collect();
    if open.is_empty() {
        return String::new();
    }
    let mut text = String::from(
        "以下步骤由用户维护。按顺序推进；每步完成前先运行验证，并用 `niuse verify --step p-N -- <command>` 记录证据；没有通过的验证不要声称完成。\n\n",
    );
    for step in open {
        text.push_str(&format!("- [ ] {} {}\n", step.label(), step.text));
    }
    if steps.iter().filter(|step| !step.done).count() > 6 {
        text.push_str("- （其余步骤省略）\n");
    }
    truncate_to_tokens(&text, PLAN_BUDGET)
}

fn goal_section(goals: &[Goal]) -> String {
