    Ok(Dashboard {
        project: spec.project,
        milestones: spec.milestones,
        layers: spec.layers,
        modules,
        relations: spec.relations,
        cards,
        docs,
        events: spec.events,
        meta,
    })
}

fn read_spec(root: &Path) -> Result<ProjectSpec> {
    let path = root.join("docs/dashboard/project.json");
    let raw = fs::read_to_string(&path).with_context(|| format!("read {}", path.display()))?;
    serde_json::from_str(&raw).with_context(|| format!("parse {}", path.display()))
}

fn load_cards(root: &Path) -> Result<Vec<CardOut>> {
    let board_dir = root.join("docs/board");
    if !board_dir.is_dir() {
        bail!("missing {}", board_dir.display());
    }

    let mut paths = Vec::new();
    for entry in
        fs::read_dir(&board_dir).with_context(|| format!("read {}", board_dir.display()))?
    {
        let path = entry?.path();
        if path.extension().and_then(|ext| ext.to_str()) == Some("md") {
            paths.push(path);
        }
    }
    paths.sort();

    let mut cards = Vec::new();
    for path in paths {
        let raw = fs::read_to_string(&path).with_context(|| format!("read {}", path.display()))?;
        let (front, body) = split_frontmatter(&raw)
            .with_context(|| format!("parse frontmatter in {}", path.display()))?;
        let front = front.with_context(|| {
            format!(
                "{}: cards require TOML frontmatter between +++ lines",
                path.display()
            )
        })?;
        let front: CardFront = toml::from_str(&front)
            .with_context(|| format!("invalid card frontmatter in {}", path.display()))?;

        cards.push(CardOut {
            front,
            body_html: render::markdown(&body),
            path: relative(root, &path),
        });
    }

    cards.sort_by(|a, b| a.front.id.cmp(&b.front.id));
    Ok(cards)
}

fn load_docs(root: &Path) -> Result<Vec<DocOut>> {
    let docs_dir = root.join("docs");
    let board_dir = docs_dir.join("board");
    let dashboard_dir = docs_dir.join("dashboard");

    let walker = WalkDir::new(&docs_dir).into_iter().filter_entry(|entry| {
        let path = entry.path();
        !(path.starts_with(&board_dir) || path.starts_with(&dashboard_dir))
    });

    let mut docs = Vec::new();
    for entry in walker {
        let entry = entry.with_context(|| format!("walk {}", docs_dir.display()))?;
        if !entry.file_type().is_file() {
            continue;
        }
        let path = entry.path();
        if path.extension().and_then(|ext| ext.to_str()) != Some("md") {
            continue;
        }

        let raw = fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
        let (front, body) = split_frontmatter(&raw)
            .with_context(|| format!("parse frontmatter in {}", path.display()))?;
        let front = front.with_context(|| {
            format!(
                "{}: docs require TOML frontmatter between +++ lines",
                path.display()
            )
        })?;
        let front: DocFront = toml::from_str(&front)
            .with_context(|| format!("invalid doc frontmatter in {}", path.display()))?;

        let excerpt = front
            .summary
            .clone()
            .filter(|summary| !summary.trim().is_empty())
            .unwrap_or_else(|| render::excerpt(&body, 180));

        docs.push(DocOut {
            front,
            body_html: render::markdown(&body),
            path: relative(root, path),
            excerpt,
        });
    }

    docs.sort_by(|a, b| {
        a.front
            .order
            .cmp(&b.front.order)
            .then_with(|| a.front.id.cmp(&b.front.id))
    });
    Ok(docs)
}

fn read_sources(root: &Path, paths: &[String]) -> Vec<SourceFile> {
    let mut sources = Vec::new();

    for relative_path in paths {
        let path = root.join(relative_path);
        if !path.is_file() {
            continue;
        }
        let Ok(raw) = fs::read_to_string(&path) else {
            continue;
        };
        let (text, truncated) = clip(&raw, 200, 30_000);

        sources.push(SourceFile {
            path: relative_path.clone(),
            language: language(relative_path).into(),
            text,
            truncated,
        });
    }

    sources
}

fn split_frontmatter(raw: &str) -> Result<(Option<String>, String)> {
    let raw = raw.strip_prefix('\u{feff}').unwrap_or(raw);
    let mut lines = raw.lines();

    if lines.next() != Some("+++") {
        return Ok((None, raw.to_string()));
    }

    let mut front = Vec::new();
    let mut body = Vec::new();
    let mut in_front = true;

    for line in lines {
        if in_front {
            if line == "+++" {
                in_front = false;
            } else {
                front.push(line);
            }
        } else {
            body.push(line);
        }
    }

use std::fs;
use std::path::Path;
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::{bail, Context, Result};
use base64::Engine as _;
use pulldown_cmark::{html, Options, Parser};
use serde::Serialize;

use crate::model::Dashboard;

pub fn markdown(input: &str) -> String {
    let mut options = Options::empty();
    options.insert(Options::ENABLE_TABLES);
    options.insert(Options::ENABLE_STRIKETHROUGH);
    options.insert(Options::ENABLE_TASKLISTS);
    options.insert(Options::ENABLE_FOOTNOTES);

    let parser = Parser::new_ext(input, options);
    let mut output = String::new();
    html::push_html(&mut output, parser);
    wrap_tables(output)
}

/// Keep wide tables readable in the narrow details pane: scroll the table
/// instead of wrapping every cell character by character.
fn wrap_tables(html: String) -> String {
    html.replace("<table>", "<div class=\"table-wrap\"><table>")
        .replace("</table>", "</table></div>")
}

pub fn excerpt(markdown: &str, limit: usize) -> String {
    let mut text = String::new();

    for line in markdown.lines() {
        let line = line.trim();
        if line.is_empty()
            || line.starts_with('#')
            || line.starts_with("```")
            || line.starts_with('|')
            || line.starts_with("---")
        {
            continue;
        }

        let cleaned =
            line.trim_start_matches(|c: char| matches!(c, '-' | '*' | '>' | ' ' | '1'..='9' | '.'));
        text.push_str(cleaned.trim());
        text.push(' ');

        if text.chars().count() >= limit {
            break;
        }
    }

    let mut out = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if out.chars().count() > limit {
        out = out.chars().take(limit).collect();
        out.push('…');
    }
    out
}

pub fn write_dashboard(root: &Path, dashboard: &Dashboard, check: bool) -> Result<()> {
    let template_path = root.join("docs/dashboard/template.html");
    let style_path = root.join("docs/dashboard/style.css");
    let app_path = root.join("docs/dashboard/app.js");

    let template = fs::read_to_string(&template_path)
        .with_context(|| format!("read {}", template_path.display()))?;
    let style = fs::read_to_string(&style_path)
        .with_context(|| format!("read {}", style_path.display()))?;
    let app =
        fs::read_to_string(&app_path).with_context(|| format!("read {}", app_path.display()))?;
    let logo_path = root.join("docs/dashboard/logo.png");
    let favicon_path = root.join("docs/dashboard/favicon.png");
    let logo = fs::read(&logo_path).with_context(|| format!("read {}", logo_path.display()))?;
    let favicon =
        fs::read(&favicon_path).with_context(|| format!("read {}", favicon_path.display()))?;
    let logo_uri = format!(
        "data:image/png;base64,{}",
        base64::engine::general_purpose::STANDARD.encode(logo)
    );
    let favicon_uri = format!(
        "data:image/png;base64,{}",
        base64::engine::general_purpose::STANDARD.encode(favicon)
    );

    let data = serde_json::to_string(dashboard).context("serialize dashboard data")?;
    let data = escape_for_script(&data);

    // Replace everything except DATA before DATA: the embedded source of
    // template.html contains the placeholders themselves, and replacing into
    // already-inserted JSON would corrupt it.
    let html = template
        .replace("{{STYLE}}", &style)
        .replace("{{APP}}", &app)
        .replace("{{LOGO}}", &logo_uri)
        .replace("{{FAVICON}}", &favicon_uri)
        .replace("{{DATA}}", &data);

    let index_path = root.join("docs/index.html");
    let model_path = root.join("docs/dashboard/model.json");
    let model = serde_json::to_string_pretty(dashboard).context("serialize dashboard model")?;
    let model = format!("{model}\n");

    if check {
        let current_html = fs::read_to_string(&index_path).unwrap_or_default();
        let current_model = fs::read_to_string(&model_path).unwrap_or_default();
        if current_html != html || current_model != model {
            bail!("dashboard is stale; run `cargo xtask dashboard`");
        }
        println!("dashboard is up to date");
        return Ok(());
    }

    fs::write(&index_path, &html).with_context(|| format!("write {}", index_path.display()))?;
    fs::write(&model_path, &model).with_context(|| format!("write {}", model_path.display()))?;

    let receipt = Receipt {
        schema_version: dashboard.meta.schema_version,
        generated_at_unix: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs(),
        git_revision: git_output(root, &["rev-parse", "--short", "HEAD"]),
        git_dirty: !git_output(root, &["status", "--porcelain"]).is_empty(),
        cards: dashboard.cards.len(),
        modules: dashboard.modules.len(),
        docs: dashboard.docs.len(),
        events: dashboard.events.len(),
        index_bytes: html.len(),
        model_bytes: model.len(),
        inputs: vec![
            "docs/dashboard/project.json".into(),
            "docs/board/*.md".into(),
            "docs/**/*.md".into(),
            "docs/dashboard/template.html".into(),
            "docs/dashboard/style.css".into(),
            "docs/dashboard/app.js".into(),
            "docs/dashboard/logo.png".into(),
            "docs/dashboard/favicon.png".into(),
        ],
    };
    let receipt_path = root.join("docs/dashboard/receipt.json");
    let receipt_json = serde_json::to_string_pretty(&receipt)?;
    fs::write(&receipt_path, format!("{receipt_json}\n"))
        .with_context(|| format!("write {}", receipt_path.display()))?;

    println!(
        "dashboard: {} cards, {} modules, {} docs → docs/index.html ({:.1} KiB)",
        dashboard.cards.len(),
        dashboard.modules.len(),
        dashboard.docs.len(),
        html.len() as f64 / 1024.0
    );
    Ok(())
}

#[derive(Debug, Serialize)]
struct Receipt {
    schema_version: u32,
    generated_at_unix: u64,
    git_revision: String,
    git_dirty: bool,
    cards: usize,
    modules: usize,
    docs: usize,
    events: usize,
    index_bytes: usize,
    model_bytes: usize,
    inputs: Vec<String>,
}

fn git_output(root: &Path, args: &[&str]) -> String {
    Command::new("git")
        .current_dir(root)
        .args(args)
        .output()
        .ok()
        .filter(|output| output.status.success())
        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_string())
        .unwrap_or_default()
}

fn escape_for_script(json: &str) -> String {
    json.replace('&', "\\u0026")
        .replace('<', "\\u003c")
        .replace('>', "\\u003e")
        .replace('\u{2028}', "\\u2028")
        .replace('\u{2029}', "\\u2029")
}

use std::collections::HashSet;
use std::path::Path;

use anyhow::{bail, Result};

use crate::model::{CardOut, CardStatus, DocOut, ModuleStatus, ProjectSpec};

pub fn validate(root: &Path, spec: &ProjectSpec, cards: &[CardOut], docs: &[DocOut]) -> Result<()> {
    let mut errors = Vec::new();

    if spec.schema_version != 1 {
        errors.push(format!(
            "unsupported schema_version {} (expected 1)",
            spec.schema_version
        ));
    }
    if spec.project.name.trim().is_empty() {
        errors.push("project.name is empty".into());
    }
    if spec.project.title.trim().is_empty() {
        errors.push("project.title is empty".into());
    }
    if spec.project.summary.trim().is_empty() {
        errors.push("project.summary is empty".into());
    }
    if spec.project.status.trim().is_empty() {
        errors.push("project.status is empty".into());
    }

    let mut milestone_ids = HashSet::new();
    for milestone in &spec.milestones {
        if !milestone_ids.insert(milestone.id.as_str()) {
            errors.push(format!("duplicate milestone id {}", milestone.id));
        }
        if milestone.title.trim().is_empty() {
            errors.push(format!("milestone {} has an empty title", milestone.id));
        }
    }
    if spec.milestones.is_empty() {
        errors.push("at least one milestone is required".into());
    }
    // Phases may overlap: M2 dogfood and M5 TUI dogfood are both active.

    let mut layer_ids = HashSet::new();
    for layer in &spec.layers {
        if !layer_ids.insert(layer.id.as_str()) {
            errors.push(format!("duplicate layer id {}", layer.id));
        }
        if layer.name.trim().is_empty() {
            errors.push(format!("layer {} has an empty name", layer.id));
        }
    }
    if spec.layers.is_empty() {
        errors.push("at least one layer is required".into());
    }

    let mut module_ids = HashSet::new();
    for module in &spec.modules {
        if !module_ids.insert(module.id.as_str()) {
            errors.push(format!("duplicate module id {}", module.id));
        }
        if !layer_ids.contains(module.layer.as_str()) {
            errors.push(format!(
                "module {} references unknown layer {}",
                module.id, module.layer
            ));
        }
        if module.status != ModuleStatus::Planned {
            if module.paths.is_empty() {
                errors.push(format!(
                    "module {} is {} but owns no paths",
                    module.id,
                    status_name(module.status)
                ));
            } else if !module.paths.iter().any(|path| root.join(path).exists()) {
                errors.push(format!(
                    "module {} is {} but none of its paths exist",
                    module.id,
                    status_name(module.status)
                ));
            }
        }
    }
    if spec.modules.is_empty() {
        errors.push("at least one module is required".into());
    }

    for relation in &spec.relations {
        if !module_ids.contains(relation.from.as_str()) {
            errors.push(format!(
                "relation references unknown module {} → {}",
                relation.from, relation.to
            ));
        }
        if !module_ids.contains(relation.to.as_str()) {
            errors.push(format!(
                "relation references unknown module {} → {}",
                relation.from, relation.to
            ));
        }
    }

    let doc_ids = docs
        .iter()
        .map(|doc| doc.front.id.as_str())
        .collect::<HashSet<_>>();
    let mut seen_docs = HashSet::new();
    for doc in docs {
        if !seen_docs.insert(doc.front.id.as_str()) {
            errors.push(format!("duplicate doc id {}", doc.front.id));
        }
        if doc.front.kind.trim().is_empty() {
            errors.push(format!("doc {} has an empty kind", doc.front.id));
        }
        if doc.front.kind == "adr" {
            let status = doc.front.status.as_deref().unwrap_or("");
            if !matches!(
                status,
                "proposed" | "accepted" | "superseded" | "rejected" | "draft"
            ) {
                errors.push(format!(
                    "doc {} is an ADR with invalid status {:?}",
                    doc.front.id, status
                ));
            }
        }
    }

    let mut card_ids = HashSet::new();
    for card in cards {
        let front = &card.front;
        if !card_ids.insert(front.id.as_str()) {
            errors.push(format!("duplicate card id {}", front.id));
        }
        if !milestone_ids.contains(front.milestone.as_str()) {
            errors.push(format!(
                "card {} references unknown milestone {}",
                front.id, front.milestone
            ));
        }
        if let Some(module) = &front.module {
            if !module_ids.contains(module.as_str()) {
                errors.push(format!(
                    "card {} references unknown module {}",
                    front.id, module
                ));
            }
        }
        for dependency in &front.depends_on {
            if dependency == &front.id {
                errors.push(format!("card {} depends on itself", front.id));
            } else if !cards.iter().any(|other| &other.front.id == dependency) {
                errors.push(format!(
                    "card {} references unknown dependency {}",
                    front.id, dependency
                ));
            }
        }
        for doc in &front.docs {
            if !doc_ids.contains(doc.as_str()) {
                errors.push(format!("card {} references unknown doc {}", front.id, doc));
            }
        }
        if !valid_date(&front.updated) {
            errors.push(format!(
                "card {} has invalid updated date {:?}",
                front.id, front.updated
            ));
        }
        if let Some(completed) = &front.completed {
            if !valid_date(completed) {
                errors.push(format!(
                    "card {} has invalid completed date {:?}",
                    front.id, completed
                ));
            }
        }
        if front.status == CardStatus::Done && front.completed.is_none() {
            errors.push(format!(
                "card {} is done but has no completed date",
                front.id
            ));
        }
        if front.status == CardStatus::Blocked
            && front
                .blocked_reason
                .as_deref()
                .unwrap_or("")
                .trim()
                .is_empty()
        {
            errors.push(format!(
                "card {} is blocked but has no blocked_reason",
                front.id
            ));
        }
        if let Some(priority) = &front.priority {
            if !matches!(priority.as_str(), "P0" | "P1" | "P2") {
                errors.push(format!(
                    "card {} has invalid priority {:?}",
